internal static class Json
{
    public static string Serialize<T>(T value)
    {
        var ser = new DataContractJsonSerializer(typeof(T));
        using var ms = new MemoryStream(); ser.WriteObject(ms, value);
        return Encoding.UTF8.GetString(ms.ToArray());
    }
    public static T? Deserialize<T>(string json) where T : class
    {
        var ser = new DataContractJsonSerializer(typeof(T));
        using var ms = new MemoryStream(Encoding.UTF8.GetBytes(json));
        return ser.ReadObject(ms) as T;
    }
}

// ffmpeg-style child process with async stdout/stderr
var psi = new ProcessStartInfo { FileName = "ffmpeg.exe", Arguments = args, UseShellExecute = false,
    RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true, StandardOutputEncoding = Encoding.UTF8 };
var proc = new Process { StartInfo = psi, EnableRaisingEvents = true };
proc.OutputDataReceived += (s, e) => { if (e.Data is { } d) Append($"[out] {d}"); };
proc.ErrorDataReceived  += (s, e) => { if (e.Data is { } d) Append($"[err] {d}"); };
var tcs = new TaskCompletionSource<int>();
proc.Exited += (s, e) => tcs.TrySetResult(proc.ExitCode);
proc.Start(); proc.BeginOutputReadLine(); proc.BeginErrorReadLine();
int code = await tcs.Task;

